from typing import Tuple


def region_capacity(width: int, depth: int) -> int:
    if width < 0 or depth < 0:
        raise ValueError("width and depth must be nonnegative")
    return (width + 1) ** depth


def minimum_depth(width: int, demand: int) -> Tuple[int, int]:
    """Return the minimal depth and its attained capacity."""
    if width <= 0 or demand < 0:
        raise ValueError("width must be positive and demand nonnegative")
    depth, capacity = 0, 1
    while capacity < demand:
        capacity *= width + 1
        depth += 1
    return depth, capacity


def exact_one_layer_width(width: int, depth: int) -> int:
    """Width of a one-layer architecture with equal model capacity."""
    return region_capacity(width, depth) - 1
